DO $clinical_size_backfill$
DECLARE original_binding text := current_setting('app.current_tenant_id',true); selected_tenant uuid;
BEGIN
  FOR selected_tenant IN SELECT DISTINCT tenant_id FROM "nightscout_migration_namespace"."activity" LOOP
    PERFORM set_config('app.current_tenant_id',selected_tenant::text,true);
    UPDATE "nightscout_migration_namespace"."activity" SET storage_bytes=pg_column_size(doc) WHERE tenant_id=selected_tenant;
  END LOOP;
  PERFORM set_config('app.current_tenant_id',COALESCE(original_binding,''),true);
END
$clinical_size_backfill$

CREATE FUNCTION "nightscout_migration_namespace".clinical_storage_size() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $clinical_size$
DECLARE measured bigint;
BEGIN
  SELECT pg_column_size(doc) INTO STRICT measured FROM "nightscout_migration_namespace"."activity" WHERE tenant_id=NEW.tenant_id AND id_kind=NEW.id_kind AND "_id"=NEW."_id";
  UPDATE "nightscout_migration_namespace"."activity" SET storage_bytes=measured WHERE tenant_id=NEW.tenant_id AND id_kind=NEW.id_kind AND "_id"=NEW."_id" AND storage_bytes IS DISTINCT FROM measured;
  RETURN NULL;
END
$clinical_size$
